-- GitHub Integration source and Git Activity read model. H2 only.
-- Existing application tables are referenced, never created or changed here.
CREATE TABLE IF NOT EXISTS backlog_git_link (is_active boolean not null, artifact_at timestamp(6) not null, artifact_id bigint not null, backlog_item_id bigint not null, created_at timestamp(6) not null, created_by bigint, id bigint generated by default as identity, item_project_id bigint, linked_at timestamp(6) not null, linked_by_user_id bigint, project_id bigint not null, reference_id bigint, repository_id bigint not null, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, link_source varchar(10) not null check (link_source in ('AUTO','MANUAL')), artifact_type varchar(20) not null, primary key (id), constraint uk_backlog_git_link unique (backlog_item_id, artifact_type, artifact_id));
CREATE TABLE IF NOT EXISTS backlog_git_link_exclusion (is_active boolean not null, artifact_id bigint not null, backlog_item_id bigint not null, created_at timestamp(6) not null, created_by bigint, excluded_at timestamp(6) not null, excluded_by_user_id bigint not null, id bigint generated by default as identity, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, artifact_type varchar(20) not null, primary key (id), constraint uk_backlog_git_link_excl unique (backlog_item_id, artifact_type, artifact_id));
CREATE TABLE IF NOT EXISTS backlog_reference (is_active boolean not null, backlog_item_id bigint, created_at timestamp(6) not null, created_by bigint, id bigint generated by default as identity, project_id bigint not null, repository_id bigint not null, resolved_at timestamp(6) not null, source_id bigint not null, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, source_field varchar(10) not null check (source_field in ('MESSAGE','TITLE','BRANCH','BODY','MERGED_PR','NONE')), source_type varchar(20) not null, status varchar(20) not null check (status in ('LINKED','INVALID','OUTSIDE_PROJECT','MISSING','EXCLUDED')), reason varchar(30) not null check (reason in ('OK','NOT_FOUND','DELETED','OTHER_PROJECT','NO_TASK_ID','UNLINKED_BY_USER')), ref_key varchar(30) not null, raw_text varchar(40), primary key (id), constraint uk_backlog_ref_source_key unique (source_type, source_id, ref_key));
CREATE TABLE IF NOT EXISTS commit_validation_result (evaluation_key varchar(48) default 'INGESTION' not null, rule_snapshot text, rule_version integer not null, commit_id bigint not null, evaluated_at timestamp(6) with time zone not null, id bigint generated by default as identity, reason varchar(1000), details TEXT, rule_type enum ('CONVENTIONAL_COMMIT','TASK_ID') not null, status enum ('FAILED','INVALID','MISSING','NOT_EVALUATED','OUTSIDE_PROJECT','PASSED') not null, primary key (id), constraint uk_git_validation_commit_rule_run unique (commit_id, rule_type, rule_version, evaluation_key));
CREATE TABLE IF NOT EXISTS commit_validation_task_reference (id bigint generated by default as identity, project_id bigint not null, task_id bigint not null, validation_result_id bigint not null, primary key (id), constraint uk_git_validation_task_reference unique (validation_result_id, task_id));
CREATE TABLE IF NOT EXISTS git_activity_change (attempts integer not null, id bigint generated by default as identity, next_attempt_at timestamp(6) with time zone not null, processed_at timestamp(6) with time zone, repository_id bigint not null, last_error varchar(160), primary key (id));
CREATE TABLE IF NOT EXISTS git_activity_demo_sprint (empty_sprint_id bigint, project_id bigint not null, report_sprint_id bigint, repository_id bigint not null, primary key (project_id));
CREATE TABLE IF NOT EXISTS git_commit (source_ingested_at timestamp with time zone, is_bot boolean not null, is_merge boolean not null, author_contributor_id bigint, committed_at timestamp(6) with time zone not null, id bigint generated by default as identity, repository_id bigint not null, sha varchar(64) not null, html_url varchar(2048), first_seen_branch varchar(255), message TEXT not null, primary key (id), constraint uk_git_commit_repository_sha unique (repository_id, sha));
CREATE TABLE IF NOT EXISTS git_commits (files_changed integer, is_active boolean not null, is_bot boolean, is_merge boolean, parent_count integer, author_github_id bigint, authored_at timestamp(6), committed_at timestamp(6) not null, created_at timestamp(6) not null, created_by bigint, id bigint generated by default as identity, ingested_at timestamp(6) not null, ingested_event_id bigint, ingested_sync_job_id bigint, project_id bigint not null, repo_external_id bigint not null, repository_id bigint not null, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, source varchar(20) not null check (source in ('WEBHOOK_PAYLOAD','COMPARE_API','LIST_COMMITS_API','GRAPHQL_HISTORY')), sha varchar(64) not null, author_login varchar(100), committer_login varchar(100), html_url varchar(500), message varchar(4000), author_email varchar(255), author_name varchar(255), committer_email varchar(255), committer_name varchar(255), first_seen_ref varchar(255) not null, primary key (id), constraint uk_git_commit_repo_sha unique (repository_id, sha));
CREATE TABLE IF NOT EXISTS git_contributor (is_bot boolean not null, external_id bigint, id bigint generated by default as identity, root_project_id bigint not null, source_contributor_id bigint, user_id bigint, login varchar(100) not null, source_identity_key varchar(320), display_name varchar(255), primary key (id), constraint uk_git_contributor_root_external unique (root_project_id, external_id));
CREATE TABLE IF NOT EXISTS git_contributors (is_active boolean not null, created_at timestamp(6) not null, created_by bigint, external_user_id bigint, first_seen_at timestamp(6), id bigint generated by default as identity, last_seen_at timestamp(6), mapped_at timestamp(6), mapped_by_user_id bigint, master_project_id bigint not null, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, user_id bigint, version bigint, login varchar(100), identity_key varchar(320) not null, display_name varchar(255), email varchar(255), map_source enum ('IDENTITY','MANUAL','OAUTH'), primary key (id), constraint uk_git_contributor_master_identity unique (master_project_id, identity_key));
CREATE TABLE IF NOT EXISTS git_installations (is_active boolean not null, account_id bigint not null, connected_at timestamp(6) not null, connected_by_user_id bigint not null, created_at timestamp(6) not null, created_by bigint, disconnected_by_user_id bigint, github_user_id bigint, id bigint generated by default as identity, installation_id bigint not null, last_checked_at timestamp(6), last_verified_at timestamp(6) not null, status_changed_at timestamp(6), tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, version bigint, account_type varchar(20) not null, repository_selection varchar(20), status varchar(20) not null check (status in ('CONNECTED','SUSPENDED','DISCONNECTED','ERROR')), status_reason varchar(50), account_login varchar(100) not null, github_user_login varchar(100), provider enum ('GITHUB') not null, primary key (id), constraint uk_git_installation_provider_installation unique (provider, installation_id));
CREATE TABLE IF NOT EXISTS git_oauth_states (is_active boolean not null, consumed_at timestamp(6), created_at timestamp(6) not null, created_by bigint, expires_at timestamp(6) not null, id bigint generated by default as identity, project_id bigint, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, user_id bigint not null, state_hash varchar(64) not null unique, outcome enum ('ACCOUNT_LINKED','CONNECTED','DENIED','IDENTITY_LINKED_ELSEWHERE','IDENTITY_MISMATCH','INSTALLATION_NOT_OWNED','INVALID_CALLBACK','LINKED_ELSEWHERE','MAPPED_TO_OTHER_MEMBER','NOT_PROJECT_MEMBER','PENDING_APPROVAL','PROVIDER_ERROR','RECONNECTED'), provider enum ('GITHUB') not null, purpose enum ('ACCOUNT_LINK','INSTALL'), primary key (id));
CREATE TABLE IF NOT EXISTS git_pull_request_reviews (is_active boolean not null, source_action_rank integer not null, created_at timestamp(6) not null, created_by bigint, dismissed_at timestamp(6), external_id bigint not null, id bigint generated by default as identity, last_event_id bigint, last_sync_job_id bigint, project_id bigint not null, pull_request_id bigint not null, repository_id bigint not null, reviewer_github_id bigint, source_updated_at timestamp(6) not null, submitted_at timestamp(6), tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, version bigint, state varchar(20) not null check (state in ('APPROVED','CHANGES_REQUESTED','COMMENTED','DISMISSED','PENDING')), last_action varchar(50), commit_sha varchar(64), reviewer_login varchar(100), html_url varchar(500), body varchar(4000), primary key (id), constraint uk_git_review_pr_external unique (pull_request_id, external_id));
CREATE TABLE IF NOT EXISTS git_pull_requests (additions integer, changed_files integer, commits_count integer, deletions integer, draft boolean not null, is_active boolean not null, number integer not null, author_github_id bigint, closed_at timestamp(6), created_at timestamp(6) not null, created_by bigint, external_id bigint not null, github_created_at timestamp(6) not null, github_updated_at timestamp(6) not null, id bigint generated by default as identity, last_event_id bigint, last_sync_job_id bigint, merged_at timestamp(6), project_id bigint not null, repo_external_id bigint not null, repository_id bigint not null, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, version bigint, state varchar(20) not null check (state in ('OPEN','CLOSED','MERGED')), last_action varchar(50), head_sha varchar(64), merge_commit_sha varchar(64), author_login varchar(100), merged_by_login varchar(100), html_url varchar(500), title varchar(500) not null, body varchar(4000), base_ref varchar(255), head_ref varchar(255), primary key (id), constraint uk_git_pr_repo_number unique (repository_id, number));
CREATE TABLE IF NOT EXISTS git_repositories (is_active boolean not null, active_external_id bigint, active_project_id bigint, commit_history_synced_at timestamp(6), created_at timestamp(6) not null, created_by bigint, external_id bigint not null, id bigint generated by default as identity, installation_ref bigint not null, last_synced_at timestamp(6), linked_at timestamp(6) not null, linked_by_user_id bigint not null, project_id bigint not null, pull_requests_synced_at timestamp(6), status_changed_at timestamp(6), tenant_id bigint not null, unlinked_at timestamp(6), unlinked_by_user_id bigint, updated_at timestamp(6) not null, updated_by bigint, version bigint, visibility varchar(20) not null, status_reason varchar(50), default_branch varchar(100), name varchar(100) not null, owner_login varchar(100) not null, full_name varchar(200) not null, html_url varchar(500) not null, provider enum ('GITHUB') not null, status enum ('ACTIVE','DISCONNECTED','ERROR','INACTIVE') not null, primary key (id), constraint uk_git_repo_active_project unique (active_project_id), constraint uk_git_repo_active_external unique (provider, active_external_id));
CREATE TABLE IF NOT EXISTS git_repository (mock_data boolean not null, active_external_id BIGINT GENERATED ALWAYS AS (CASE WHEN status <> 'INACTIVE' THEN external_id ELSE NULL END), active_root_project_id BIGINT GENERATED ALWAYS AS (CASE WHEN status <> 'INACTIVE' THEN root_project_id ELSE NULL END), external_id bigint not null, id bigint generated by default as identity, last_synced_at timestamp(6) with time zone, linked_at timestamp(6) with time zone, root_project_id bigint not null, source_repository_id bigint unique, unlinked_at timestamp(6) with time zone, name varchar(100) not null, owner varchar(100) not null, full_name varchar(200) not null, html_url varchar(2048), default_branch varchar(255), status enum ('ACTIVE','DISCONNECTED','ERROR','INACTIVE') not null, sync_status enum ('ERROR','NOT_SYNCED','PARTIAL','READY','SYNCING') not null, primary key (id), constraint uk_git_repository_root_external unique (root_project_id, external_id), constraint uk_git_repository_active_root unique (active_root_project_id), constraint uk_git_repository_active_external unique (active_external_id));
CREATE TABLE IF NOT EXISTS git_sync_jobs (attempt_count integer not null, is_active boolean not null, max_attempts integer not null, pages_done integer, pr_pages_done integer, commit_since timestamp(6), created_at timestamp(6) not null, created_by bigint, finished_at timestamp(6), id bigint generated by default as identity, next_run_at timestamp(6) not null, pr_since timestamp(6), repository_id bigint not null, requested_by_user_id bigint, resumed_from_job_id bigint, started_at timestamp(6), tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, version bigint, status varchar(20) not null check (status in ('PENDING','RUNNING','SUCCEEDED','PARTIAL','FAILED')), type varchar(20) not null check (type in ('INITIAL','MANUAL','SCHEDULED','WEBHOOK')), phase varchar(30) check (phase in ('METADATA','COMMITS','PULL_REQUESTS','DONE')), error_code varchar(50), commit_head_oid varchar(64), dedupe_key varchar(100), error_message varchar(500), commit_branch varchar(255), commit_cursor varchar(255), pr_cursor varchar(255), stats_json clob, primary key (id), constraint uk_git_sync_dedupe unique (dedupe_key));
CREATE TABLE IF NOT EXISTS git_webhook_events (attempts integer not null, is_active boolean not null, partial_result boolean, payload_bytes integer not null, records_processed integer, created_at timestamp(6) not null, created_by bigint, hook_id bigint, id bigint generated by default as identity, installation_id bigint, installation_ref bigint, next_attempt_at timestamp(6) not null, payload_purged_at timestamp(6), processed_at timestamp(6), processing_started_at timestamp(6), received_at timestamp(6) not null, repo_external_id bigint, repository_ref bigint, tenant_id bigint, updated_at timestamp(6) not null, updated_by bigint, version bigint, status varchar(20) not null check (status in ('RECEIVED','PROCESSING','PROCESSED','IGNORED','FAILED_RETRYABLE','FAILED')), action varchar(50), event_type varchar(50) not null, delivery_id varchar(64) not null, sender_login varchar(100), repo_full_name varchar(200), last_error varchar(1000), payload clob, provider enum ('GITHUB') not null, primary key (id), constraint uk_git_webhook_delivery unique (provider, delivery_id));
CREATE TABLE IF NOT EXISTS project_dev_rule (enabled boolean not null, scope_required boolean not null, version integer not null, created_at timestamp(6) with time zone not null, created_by bigint, id bigint generated by default as identity, project_id bigint not null, allowed_commit_types varchar(160) not null, task_key_pattern varchar(160) not null, rule_type enum ('CONVENTIONAL_COMMIT','TASK_ID') not null, primary key (id), constraint uk_git_dev_rule_root_type_version unique (project_id, rule_type, version));
CREATE TABLE IF NOT EXISTS pull_request (is_draft boolean not null, number integer not null, author_contributor_id bigint not null, closed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, external_id bigint not null, first_review_at timestamp(6) with time zone, gh_created_at timestamp(6) with time zone not null, gh_updated_at timestamp(6) with time zone not null, id bigint generated by default as identity, merged_at timestamp(6) with time zone, repository_id bigint not null, updated_at timestamp(6) with time zone not null, source_branch varchar(200) not null, target_branch varchar(200) not null, title varchar(500) not null, html_url varchar(2048), body TEXT, state enum ('CLOSED','MERGED','OPEN') not null, primary key (id), constraint uk_pull_request_repository_number unique (repository_id, number), constraint uk_pull_request_repository_external unique (repository_id, external_id));
CREATE TABLE IF NOT EXISTS pull_request_review (is_self_review boolean not null, created_at timestamp(6) with time zone not null, external_id bigint not null, id bigint generated by default as identity, pull_request_id bigint not null, reviewer_contributor_id bigint not null, source_updated_at timestamp(6) with time zone, submitted_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, state enum ('APPROVED','CHANGES_REQUESTED','COMMENTED','DISMISSED','PENDING') not null, primary key (id), constraint uk_pull_request_review_source_id unique (pull_request_id, external_id));
CREATE TABLE IF NOT EXISTS task_git_link (commit_id bigint, id bigint generated by default as identity, linked_at timestamp(6) with time zone not null, linked_by bigint, pull_request_id bigint, task_id bigint not null, source enum ('AUTO','MANUAL') not null, primary key (id), constraint uk_task_git_link_task_commit unique (task_id, commit_id), constraint uk_task_git_link_task_pull_request unique (task_id, pull_request_id), check ((commit_id is not null and pull_request_id is null) or (commit_id is null and pull_request_id is not null)));
CREATE TABLE IF NOT EXISTS user_git_identities (is_active boolean not null, created_at timestamp(6) not null, created_by bigint, external_user_id bigint not null, id bigint generated by default as identity, tenant_id bigint not null, updated_at timestamp(6) not null, updated_by bigint, user_id bigint not null, verified_at timestamp(6) not null, version bigint, login varchar(100) not null, avatar_url varchar(500), provider enum ('GITHUB') not null, source enum ('INSTALLATION','LOGIN','OAUTH') not null, primary key (id), constraint uk_user_git_identity_external unique (provider, external_user_id), constraint uk_user_git_identity_user unique (user_id, provider));
