create table if not exists git_validation_run (
    id bigint generated by default as identity primary key,
    root_project_id bigint not null,
    target_commit_id bigint,
    operation_key varchar(48) not null,
    completed_at timestamp(6) with time zone not null,
    constraint uk_git_validation_run_key unique(root_project_id, operation_key),
    constraint fk_git_validation_run_project foreign key(root_project_id) references projects,
    constraint fk_git_validation_run_commit foreign key(target_commit_id) references git_commit
);
create table if not exists git_validation_run_result (
    run_id bigint not null,
    result_id bigint not null,
    constraint uk_git_validation_run_result unique(run_id, result_id),
    constraint fk_git_validation_run_result_run foreign key(run_id) references git_validation_run,
    constraint fk_git_validation_run_result_result foreign key(result_id) references commit_validation_result
);

alter table git_sync_jobs add column if not exists claim_token varchar(36);
alter table git_sync_jobs add column if not exists last_claimed_at timestamp(6);

create table if not exists git_backlog_task_key (
    sprint_backlog_id bigint primary key,
    tenant_id bigint,
    task_key varchar(20),
    task_key_number bigint,
    constraint uk_git_backlog_task_key unique(tenant_id, task_key),
    constraint fk_git_backlog_task_key_task foreign key(sprint_backlog_id) references sprint_backlog on delete cascade,
    constraint fk_git_backlog_task_key_tenant foreign key(tenant_id) references tenants
);
create index if not exists idx_git_backlog_task_key on git_backlog_task_key(task_key);
create table if not exists git_task_key_sequence (
    id bigint generated by default as identity primary key,
    tenant_id bigint not null,
    prefix varchar(8) not null,
    next_number bigint not null,
    updated_at timestamp(6) not null,
    constraint uk_git_task_key_sequence unique(tenant_id, prefix)
);
alter table git_backlog_task_key add constraint if not exists fk_git_backlog_task_key_tenant foreign key(tenant_id) references tenants;
-- The counter reserves numbers in REQUIRES_NEW before the owning tenant transaction commits.
alter table git_task_key_sequence drop constraint if exists fk_git_task_key_sequence_tenant;
